        this.addAnnotation((ENamedElement)this.linEventTriggeredFrameEClass, source, new String[]{"documentation", "An event triggered frame is used as a placeholder to allow multiple slave nodes to provide its response.\r\n\r\nThe header of an event triggered frame is transmitted when a frame slot allocated to the event triggered frame is processed. The publisher of an associated unconditional frame shall only transmit the response if at least one of the signals carried in its unconditional frame is updated. The LIN Master discovers and purges collisions with the collisionResolvingScheduleTable. \r\n\r\nThe event controlled frame shall not contain any Pdus."});
        this.addAnnotation((ENamedElement)this.getLinEventTriggeredFrame_CollisionResolvingSchedule(), source, new String[]{"documentation", "Reference to the schedule table, which resolves a collision."});
        this.addAnnotation((ENamedElement)this.getLinEventTriggeredFrame_LinUnconditionalFrames(), source, new String[]{"documentation", "A list of slaves can respond to the master request if at least one of the signals carried in its unconditional frame is updated. \r\n\r\nFor each response a LinFrameTriggering and a LinUnconditionalFrame shall be defined. Within a channel a LIN Frame shall be referenced by only one FrameTriggering. This allows a derivation of the identifier of a substituted Frame. The identifier is specified in FrameTriggering element. \r\n\r\nThe Unconditional frames associated with an event triggered frame shall:\r\n- have equal length.\r\n- use the same checksum model (i.e. mixing LIN 1.x and LIN 2.x frames is not allowed).\r\n- reserve the first data field to its protected identifier (even if the associated unconditional frame is scheduled as a unconditional frame in the same or another schedule table).\r\n- be published by different slave nodes.\r\n- shall not be included directly in the same schedule table as the event triggered frame is scheduled.\r\n"});
        this.addAnnotation((ENamedElement)this.linUnconditionalFrameEClass, source, new String[]{"documentation", "Unconditional frames carry signals. The master sends a frame header in a scheduled frame slot and the designated slave node fills the frame with data."});
        this.addAnnotation((ENamedElement)this.linSporadicFrameEClass, source, new String[]{"documentation", "A sporadic frame is a group of unconditional frames that share the same frame slot. The sporadic frame shall not contain any Pdus."});
        this.addAnnotation((ENamedElement)this.getLinSporadicFrame_SubstitutedFrames(), source, new String[]{"documentation", "Reference to a group of unconditional frames that share the same frame slot. In case that more than one of the declared frames needs to be transferred, the one first listed shall be chosen. \r\n\r\nWithin a channel a LIN Frame shall be referenced by only one FrameTriggering. This allows a derivation of the identifier of a substituted Frame. The identifier is specified in FrameTriggering element. \r\n\r\nA LinUnconditionalFrame associated with a LinSporadicFrame may not be allocated in the same LinScheduleTable as the sporadic frame."});
        this.addAnnotation((ENamedElement)this.saveConfigurationEntryEClass, source, new String[]{"documentation", "This service is used to notify a slave node to store its configuration."});
        this.addAnnotation((ENamedElement)this.unassignFrameIdEClass, source, new String[]{"documentation", "Schedule entry for an Unassign Frame Id master request where the protected identifier is assigned the value 0x40. This will disable reception/transmission of a previously dynamically assigned frame identifier."});
        this.addAnnotation((ENamedElement)this.getUnassignFrameId_UnassignedFrameTriggering(), source, new String[]{"documentation", "The frame whose identifier is reset by this assignment."});
